//! O driver PnP da HAL (\Driver\ACPI_HAL): o computador ACPI e o
//! dispositivo ACPI raiz.
//!
//! No NT a HAL relata o computador como o dispositivo da raiz
//! `ROOT\ACPI_HAL\0000` (HardwareID `acpiapic`, CompatibleIDs
//! `DETECTEDInternal\ACPI_HAL` e `DETECTED\ACPI_HAL`, serviço
//! `\Driver\ACPI_HAL`); o HalpAddDevice cria sobre ele o FDO da HAL e um
//! único filho, o PDO `AcpiRootPdo` (FILE_DEVICE_BUS_EXTENDER,
//! FILE_AUTOGENERATED_DEVICE_NAME), que o PnP instala pelo acpi.inf
//! (`*pnp0c08`, serviço ACPI): é sobre ele que o acpi.sys põe o FDO da
//! árvore ACPI. O HalpDispatchPnp do ntoskrnl 19041 responde pelo PDO:
//! - QUERY_ID: DeviceID e HardwareIDs `ACPI_HAL\PNP0C08`, `*PNP0C08`;
//!   InstanceID `0`; o resto, STATUS_NOT_SUPPORTED;
//! - QUERY_CAPABILITIES: UniqueID e SilentInstall (sem Lock, Eject,
//!   Removable, Dock e RawDeviceOK), Address e UINumber 0xFFFFFFFF, D0 em
//!   S0 e D3 em S4/S5, latências zero;
//! - QUERY_INTERFACE (o HalpQueryInterface): GUID_BUS_INTERFACE_STANDARD,
//!   pelo qual o acpi.sys passa ao pci.sys o adaptador de DMA da HAL
//!   (HalPnpGetDmaAdapter), e GUID_DMA_CACHE_COHERENCY_INTERFACE;
//! - START e as consultas de parada e remoção, QUERY_PNP_DEVICE_STATE e
//!   DEVICE_USAGE_NOTIFICATION: sucesso; TargetDeviceRelation: o próprio PDO;
//! - o resto mantém o status recebido.
//!
//! O computador (`ROOT\ACPI_HAL\0000`) entra como barramento da plataforma
//! sob HTREE\ROOT\0, com o próprio kernel como driver (o FDO da HAL não é um
//! DEVICE_OBJECT à parte): o PDO dele responde ao QUERY_ID como o FDO e a
//! raiz juntos e as BusRelations dele são o AcpiRootPdo.
//!
//!
//! Os requisitos e a configuração de boot do AcpiRootPdo
//! (HalpQueryAcpiResourceRequirements e HalpQueryResources) são os vetores
//! da IDT que a HAL deixa para os dispositivos, um descritor de interrupção
//! exclusivo por vetor (InterfaceType PNPBus, barramento -1): com o modelo
//! APIC e sem controladores secundários, de 0xCD menos as entradas da tabela
//! de remapeamento por processador (150) até 0xCC. O acpi.sys guarda a lista
//! bruta do START como os vetores da raiz (AcpiIrqGetRootResourceList) e
//! reserva para os processadores os que ficam fora dela. A entrega real das
//! interrupções de dispositivo continua pelo 8259 no vetor da linha
//! (`0x20 + IRQ`); estes vetores só alimentam a contabilidade do acpi.sys.

use alloc::string::String;
use alloc::vec::Vec;

use crate::hal::amd64::routine_stubs::{self, Routine};
use crate::ntos::inc::types::extra_storage::{BusInterfaceStandard, Interface};
use crate::ntos::inc::types::{BusQueryIdType, DeviceCapabilities, DeviceObject, DevicePowerState, DeviceRelationType, DeviceRelations, IoStackLocation, Irp, NtStruct};
use crate::ntos::init::exports::Call;
use crate::ntos::io::io_manager::{self, irp_mj, irp_mn};
use crate::ntos::mm::guest_memory as guest;
use crate::ntos::ob::objects::device as device_objects;
use crate::rtl::{KernelError, SpinLock};

/// PDOs da HAL (0 antes do `create`).
struct HalDevices {
    /// O computador, `ROOT\ACPI_HAL\0000`.
    computer: u64,
    /// AcpiRootPdo, `ACPI_HAL\PNP0C08\0`.
    acpi_root: u64,
}

static DEVICES: SpinLock<HalDevices> = SpinLock::new(HalDevices { computer: 0, acpi_root: 0 });

const IO_TYPE_DEVICE: i16 = 3;
const FILE_DEVICE_BUS_EXTENDER: u32 = 0x2A;
const FILE_AUTOGENERATED_DEVICE_NAME: u32 = 0x80;
/// IRP_MN_QUERY_PNP_DEVICE_STATE e IRP_MN_DEVICE_USAGE_NOTIFICATION.
const QUERY_PNP_DEVICE_STATE: u8 = 0x14;
const DEVICE_USAGE_NOTIFICATION: u8 = 0x16;
const STATUS_NOT_SUPPORTED: i32 = 0xC000_00BB_u32 as i32;

/// HalAcpiHardwareIdString e HalInstanceIdString.
const ACPI_ROOT_IDS: [&str; 2] = ["ACPI_HAL\\PNP0C08", "*PNP0C08"];
const INSTANCE_ID: &str = "0";
/// HalHardwareIdString e os CompatibleIDs do dispositivo relatado.
const COMPUTER_HARDWARE_ID: &str = "acpiapic";
const COMPUTER_COMPATIBLE_IDS: [&str; 2] = ["DETECTEDInternal\\ACPI_HAL", "DETECTED\\ACPI_HAL"];

fn free_pdo(pointer: u64) {
    guest::free_bytes(pointer);
}

/// Um PDO da HAL (IoCreateDevice com FILE_DEVICE_BUS_EXTENDER e
/// DO_DEVICE_INITIALIZING já limpo).
fn create_pdo(characteristics: u32) -> Result<u64, KernelError> {
    let pdo = guest::alloc_bytes(DeviceObject::SIZE + 0x30);
    // SAFETY: bloco zerado recém-alocado do tamanho de um DEVICE_OBJECT.
    let device = unsafe { DeviceObject::at(pdo) };
    device.type_.set(IO_TYPE_DEVICE);
    device.size.set(DeviceObject::SIZE as u16);
    device.reference_count.set(1);
    device.device_type.set(FILE_DEVICE_BUS_EXTENDER);
    device.characteristics.set(characteristics);
    device.stack_size.set(1);
    device.device_extension.set(pdo + DeviceObject::SIZE);
    device_objects::register(pdo, Some(free_pdo), None)?;
    crate::ntos::io::pnp::publish_autogenerated_pdo(pdo)?;
    Ok(pdo)
}

/// Cria (uma vez) o computador e o AcpiRootPdo e passa a responder por
/// eles. Devolve o PDO do computador, o barramento da plataforma.
pub fn create() -> Result<u64, KernelError> {
    {
        let devices = DEVICES.lock();
        if devices.computer != 0 {
            return Ok(devices.computer);
        }
    }
    let computer = create_pdo(0)?;
    let acpi_root = create_pdo(FILE_AUTOGENERATED_DEVICE_NAME)?;
    {
        let mut devices = DEVICES.lock();
        devices.computer = computer;
        devices.acpi_root = acpi_root;
    }
    io_manager::register_pdo_native_answerer(answer_irp);
    Ok(computer)
}

/// O AcpiRootPdo (0 antes do `create`).
pub fn acpi_root_pdo() -> u64 {
    DEVICES.lock().acpi_root
}

/// Strings UTF-16 em pool (MULTI_SZ quando há várias).
fn pool_strings(items: &[&str]) -> u64 {
    let mut bytes = Vec::new();
    for item in items {
        bytes.extend(item.encode_utf16().flat_map(|unit| unit.to_le_bytes()));
        bytes.extend_from_slice(&[0, 0]);
    }
    bytes.extend_from_slice(&[0, 0]);
    let buffer = guest::alloc_bytes(bytes.len() as u64);
    guest::write_bytes(buffer, &bytes);
    buffer
}

/// DEVICE_RELATIONS em pool com os PDOs referenciados.
fn relations(devices: &[u64]) -> u64 {
    let size = DeviceRelations::SIZE + devices.len().saturating_sub(1) as u64 * 8;
    let address = guest::alloc_bytes(size);
    // SAFETY: DEVICE_RELATIONS recém-alocada com `devices.len()` entradas.
    let list = unsafe { DeviceRelations::at(address) };
    list.count.set(devices.len() as u32);
    // SAFETY: Objects[] segue o cabeçalho na mesma alocação.
    let objects = unsafe { crate::ntos::inc::field::Field::<u64>::array_at(list.objects[0].address(), devices.len()) };
    for (slot, &device) in objects.iter().zip(devices) {
        let _ = device_objects::reference(device);
        slot.set(device);
    }
    address
}

/// O IO_STACK_LOCATION corrente de um IRP vivo.
fn current_stack_location(packet: u64) -> (&'static Irp, &'static IoStackLocation) {
    // SAFETY: IRP vivo entregue ao PDO.
    let irp = unsafe { Irp::at(packet) };
    // SAFETY: a pilha corrente do IRP.
    (irp, unsafe { IoStackLocation::at(irp.tail.overlay.current_stack_location.get()) })
}

/// HalpDispatchPnp/HalpDispatchPower para os PDOs da HAL.
fn answer_irp(device: u64, packet: u64) -> Option<i32> {
    let (computer, acpi_root) = {
        let devices = DEVICES.lock();
        (devices.computer, devices.acpi_root)
    };
    if device == 0 || (device != computer && device != acpi_root) {
        return None;
    }
    let (irp, location) = current_stack_location(packet);
    let mut status = irp.io_status.status.get();
    let mut information = irp.io_status.information.get();
    match location.major_function.get() {
        irp_mj::POWER => status = 0,
        irp_mj::PNP => {
            let answer = if device == acpi_root { answer_acpi_root(device, location) } else { answer_computer(device, acpi_root, location) };
            if let Some((new_status, new_information)) = answer {
                status = new_status;
                information = new_information;
            }
        }
        _ => {}
    }
    irp.io_status.status.set(status);
    irp.io_status.information.set(information);
    io_manager::iof_complete_request(packet);
    Some(status)
}

/// O PDO do AcpiRootPdo (o ramo 0xC0 do HalpDispatchPnp).
fn answer_acpi_root(device: u64, location: &IoStackLocation) -> Option<(i32, u64)> {
    match location.minor_function.get() {
        // START, QUERY_REMOVE, REMOVE, CANCEL_REMOVE, STOP, QUERY_STOP e
        // CANCEL_STOP.
        0..=6 | QUERY_PNP_DEVICE_STATE | DEVICE_USAGE_NOTIFICATION => Some((0, 0)),
        irp_mn::QUERY_DEVICE_RELATIONS => (location.parameters.query_device_relations.type_.get() == DeviceRelationType::TARGET_DEVICE_RELATION).then(|| (0, relations(&[device]))),
        irp_mn::QUERY_CAPABILITIES => {
            // SAFETY: DEVICE_CAPABILITIES do IRP.
            let capabilities = unsafe { DeviceCapabilities::at(location.parameters.device_capabilities.capabilities.get()) };
            if capabilities.version.get() != 1 {
                return None;
            }
            fill_capabilities(capabilities);
            Some((0, 0))
        }
        irp_mn::QUERY_RESOURCE_REQUIREMENTS => Some((0, acpi_root_requirements())),
        irp_mn::QUERY_RESOURCES => Some((0, acpi_root_boot_configuration())),
        irp_mn::QUERY_INTERFACE => query_interface(location),
        irp_mn::QUERY_ID => match location.parameters.query_id.id_type.get() {
            BusQueryIdType::BUS_QUERY_DEVICE_ID | BusQueryIdType::BUS_QUERY_HARDWARE_I_DS => Some((0, pool_strings(&ACPI_ROOT_IDS))),
            BusQueryIdType::BUS_QUERY_INSTANCE_ID => Some((0, pool_strings(&[INSTANCE_ID]))),
            _ => Some((STATUS_NOT_SUPPORTED, 0)),
        },
        _ => None,
    }
}

/// GUID_BUS_INTERFACE_STANDARD {496b8280-6f25-11d0-beaf-08002be2092f}.
const GUID_BUS_INTERFACE_STANDARD: [u8; 16] = [0x80, 0x82, 0x6B, 0x49, 0x25, 0x6F, 0xD0, 0x11, 0xBE, 0xAF, 0x08, 0x00, 0x2B, 0xE2, 0x09, 0x2F];
/// GUID_DMA_CACHE_COHERENCY_INTERFACE {b520f7fa-8a5a-4e40-a3f6-6be1e162d935}.
const GUID_DMA_CACHE_COHERENCY_INTERFACE: [u8; 16] = [0xFA, 0xF7, 0x20, 0xB5, 0x5A, 0x8A, 0x40, 0x4E, 0xA3, 0xF6, 0x6B, 0xE1, 0xE1, 0x62, 0xD9, 0x35];
const STATUS_BUFFER_TOO_SMALL: i32 = 0xC000_0023_u32 as i32;
const STATUS_INVALID_PARAMETER: i32 = 0xC000_000D_u32 as i32;
/// Tamanhos das interfaces (wdm.h).
const BUS_INTERFACE_STANDARD_SIZE: u16 = 0x40;
const DMA_CACHE_COHERENCY_INTERFACE_SIZE: u16 = 0x28;

/// Rotinas da HAL entregues por ponteiro nas interfaces do AcpiRootPdo.
pub const ROUTINES: &[Routine] = &[
    // InterfaceReference/InterfaceDereference: retornam sem efeito.
    Routine { name: "HalpPnpInterfaceReference", handler: interface_reference },
    // HalPnpGetDmaAdapter: o HalpGetAdapter com a DEVICE_DESCRIPTION.
    Routine { name: "HalPnpGetDmaAdapter", handler: get_dma_adapter },
    // SetBusData/GetBusData do barramento da HAL: nenhum byte (0).
    Routine { name: "HalpPnpBusData", handler: bus_data },
];

fn interface_reference(_: &Call) -> Result<u64, KernelError> {
    Ok(0)
}

/// HalPnpGetDmaAdapter(Context, DeviceDescription, NumberOfMapRegisters*).
fn get_dma_adapter(call: &Call) -> Result<u64, KernelError> {
    Ok(crate::hal::dma::get_adapter(call.arg(1), call.arg(2), call.arg(3)))
}

fn bus_data(_: &Call) -> Result<u64, KernelError> {
    Ok(0)
}

/// HalpQueryInterface do AcpiRootPdo: GUID_BUS_INTERFACE_STANDARD (Size
/// 0x40, versão 1; o Context é o InterfaceSpecificData do pedido, que o
/// acpi.sys preenche com o PDO de quem pergunta; TranslateBusAddress nulo;
/// GetDmaAdapter = HalPnpGetDmaAdapter) e GUID_DMA_CACHE_COHERENCY_INTERFACE
/// (Size 0x28, versão 1, coerente). Information = o tamanho escrito.
fn query_interface(location: &IoStackLocation) -> Option<(i32, u64)> {
    let parameters = &location.parameters.query_interface;
    let guid: [u8; 16] = guest::read_bytes(parameters.interface_type.get(), 16).try_into().ok()?;
    let (size, version, interface, context) = (parameters.size.get(), parameters.version.get(), parameters.interface.get(), parameters.interface_specific_data.get());
    if guid == GUID_BUS_INTERFACE_STANDARD {
        if size < BUS_INTERFACE_STANDARD_SIZE {
            return Some((STATUS_BUFFER_TOO_SMALL, BUS_INTERFACE_STANDARD_SIZE as u64));
        }
        if context == 0 {
            return Some((STATUS_INVALID_PARAMETER, BUS_INTERFACE_STANDARD_SIZE as u64));
        }
        // SAFETY: buffer INTERFACE do pedido com pelo menos 0x40 bytes.
        let bus = unsafe { BusInterfaceStandard::at(interface) };
        bus.interface.size.set(BUS_INTERFACE_STANDARD_SIZE);
        bus.interface.version.set(1);
        bus.interface.context.set(context);
        bus.interface.interface_reference.set(routine_stubs::address("HalpPnpInterfaceReference").ok()?);
        bus.interface.interface_dereference.set(routine_stubs::address("HalpPnpInterfaceReference").ok()?);
        bus.translate_bus_address.set(0);
        bus.get_dma_adapter.set(routine_stubs::address("HalPnpGetDmaAdapter").ok()?);
        bus.set_bus_data.set(routine_stubs::address("HalpPnpBusData").ok()?);
        bus.get_bus_data.set(routine_stubs::address("HalpPnpBusData").ok()?);
        return Some((0, BUS_INTERFACE_STANDARD_SIZE as u64));
    }
    if guid == GUID_DMA_CACHE_COHERENCY_INTERFACE {
        if size < DMA_CACHE_COHERENCY_INTERFACE_SIZE {
            return Some((STATUS_BUFFER_TOO_SMALL, 0));
        }
        if version == 0 {
            return Some((STATUS_NOT_SUPPORTED, 0));
        }
        // SAFETY: buffer INTERFACE do pedido com pelo menos 0x28 bytes.
        let header = unsafe { Interface::at(interface) };
        header.size.set(DMA_CACHE_COHERENCY_INTERFACE_SIZE);
        header.version.set(1);
        header.context.set(0);
        header.interface_reference.set(routine_stubs::address("HalpPnpInterfaceReference").ok()?);
        header.interface_dereference.set(routine_stubs::address("HalpPnpInterfaceReference").ok()?);
        // DMA_CACHE_COHERENCY_INTERFACE.CacheCoherent.
        guest::write8(interface + 0x20, 1);
        return Some((0, DMA_CACHE_COHERENCY_INTERFACE_SIZE as u64));
    }
    None
}

/// Os vetores da IDT para dispositivos (HalpQueryAcpiResourceRequirements):
/// [0xCD - entradas de IRT por processador, 0xCD); o HalpInterruptGetIrtInfo
/// dá 150 entradas por processador.
fn device_vectors() -> core::ops::Range<u32> {
    const IRT_ENTRIES_PER_PROCESSOR: u32 = 0x96;
    const LAST_DEVICE_VECTOR: u32 = 0xCD;
    LAST_DEVICE_VECTOR - IRT_ENTRIES_PER_PROCESSOR..LAST_DEVICE_VECTOR
}

/// INTERFACE_TYPE PNPBus e CmResourceTypeInterrupt/CmResourceShareDeviceExclusive.
const PNP_BUS: u32 = 0xF;
const TYPE_INTERRUPT: u8 = 2;
const SHARE_DEVICE_EXCLUSIVE: u8 = 1;

/// IO_RESOURCE_REQUIREMENTS_LIST em pool: uma lista (versão e revisão 1)
/// com um descritor de interrupção por vetor (Mínimo = Máximo = vetor).
fn acpi_root_requirements() -> u64 {
    let vectors = device_vectors();
    let count = vectors.len() as u32;
    let size = 0x48 + (count - 1) * 0x20;
    let list = guest::alloc_bytes(size as u64);
    guest::write32(list, size);
    guest::write32(list + 4, PNP_BUS);
    guest::write32(list + 8, 0xFFFF_FFFF);
    guest::write32(list + 0x1C, 1);
    guest::write32(list + 0x20, 0x0001_0001);
    guest::write32(list + 0x24, count);
    for (index, vector) in vectors.enumerate() {
        let descriptor = list + 0x28 + index as u64 * 0x20;
        guest::write8(descriptor + 1, TYPE_INTERRUPT);
        guest::write8(descriptor + 2, SHARE_DEVICE_EXCLUSIVE);
        guest::write32(descriptor + 8, vector);
        guest::write32(descriptor + 0xC, vector);
    }
    list
}

/// CM_RESOURCE_LIST em pool com os mesmos vetores (HalpQueryResources):
/// Level = HalConvertDeviceIdtToIrql(vetor), Vector = vetor, afinidade de
/// todos os processadores.
fn acpi_root_boot_configuration() -> u64 {
    let vectors = device_vectors();
    let count = vectors.len() as u32;
    let list = guest::alloc_bytes((count * 20 + 0x27) as u64);
    guest::write32(list, 1);
    guest::write32(list + 4, PNP_BUS);
    guest::write32(list + 8, 0xFFFF_FFFF);
    guest::write32(list + 0xC, 0x0001_0001);
    guest::write32(list + 0x10, count);
    for (index, vector) in vectors.enumerate() {
        let descriptor = list + 0x14 + index as u64 * 20;
        guest::write8(descriptor, TYPE_INTERRUPT);
        guest::write8(descriptor + 1, SHARE_DEVICE_EXCLUSIVE);
        guest::write16(descriptor + 4, crate::hal::interrupt_targets::device_idt_to_irql(vector) as u16);
        guest::write32(descriptor + 8, vector);
        guest::write64(descriptor + 0xC, u64::MAX);
    }
    list
}

/// QUERY_CAPABILITIES do AcpiRootPdo: limpa LockSupported, EjectSupported,
/// Removable, DockDevice e RawDeviceOK, liga UniqueID e SilentInstall;
/// Address/UINumber 0xFFFFFFFF; D0 em S0, D3 em S4 e S5; latências zero.
fn fill_capabilities(capabilities: &DeviceCapabilities) {
    let bits = capabilities.bitfield_4.get();
    capabilities.bitfield_4.set((bits & 0xFFFF_FEC3) | 0xC0);
    capabilities.address.set(0xFFFF_FFFF);
    capabilities.ui_number.set(0xFFFF_FFFF);
    capabilities.device_state[1].set(DevicePowerState::POWER_DEVICE_D0);
    capabilities.device_state[5].set(DevicePowerState::POWER_DEVICE_D3);
    capabilities.device_state[6].set(DevicePowerState::POWER_DEVICE_D3);
    capabilities.d1_latency.set(0);
    capabilities.d2_latency.set(0);
    capabilities.d3_latency.set(0);
}

/// O computador: o FDO da HAL (BusRelations com o AcpiRootPdo, QUERY_ID com
/// `acpiapic`) e o PDO da raiz (DeviceID `ROOT\ACPI_HAL`, instância `0000`,
/// UniqueID: o caminho da raiz já é único).
fn answer_computer(device: u64, acpi_root: u64, location: &IoStackLocation) -> Option<(i32, u64)> {
    match location.minor_function.get() {
        0..=6 | QUERY_PNP_DEVICE_STATE | DEVICE_USAGE_NOTIFICATION => Some((0, 0)),
        irp_mn::QUERY_DEVICE_RELATIONS => match location.parameters.query_device_relations.type_.get() {
            DeviceRelationType::BUS_RELATIONS => Some((0, relations(&[acpi_root]))),
            DeviceRelationType::TARGET_DEVICE_RELATION => Some((0, relations(&[device]))),
            _ => None,
        },
        irp_mn::QUERY_CAPABILITIES => {
            // SAFETY: DEVICE_CAPABILITIES do IRP.
            let capabilities = unsafe { DeviceCapabilities::at(location.parameters.device_capabilities.capabilities.get()) };
            capabilities.set_unique_id(1);
            capabilities.set_silent_install(1);
            Some((0, 0))
        }
        irp_mn::QUERY_ID => {
            let strings: Vec<String> = match location.parameters.query_id.id_type.get() {
                BusQueryIdType::BUS_QUERY_DEVICE_ID => alloc::vec![String::from("ROOT\\ACPI_HAL")],
                BusQueryIdType::BUS_QUERY_INSTANCE_ID => alloc::vec![String::from("0000")],
                BusQueryIdType::BUS_QUERY_HARDWARE_I_DS => alloc::vec![String::from(COMPUTER_HARDWARE_ID)],
                BusQueryIdType::BUS_QUERY_COMPATIBLE_I_DS => COMPUTER_COMPATIBLE_IDS.iter().map(|id| String::from(*id)).collect(),
                _ => return None,
            };
            let borrowed: Vec<&str> = strings.iter().map(String::as_str).collect();
            Some((0, pool_strings(&borrowed)))
        }
        _ => None,
    }
}
